import {
  motion,
  useAnimationFrame,
  useMotionValue,
  useSpring,
  useTransform,
  useVelocity,
} from 'framer-motion';
import type { MotionValue } from 'framer-motion';
import ScrollShell from './ScrollShell';

const PHRASE = '滚动越快 · 我越快 · ';

/** wrap v into [min, max) — local helper so we never depend on lib internals */
function wrapRange(min: number, max: number, v: number) {
  const range = max - min;
  return ((((v - min) % range) + range) % range) + min;
}

function MarqueeCopy() {
  return (
    <div className="flex shrink-0 whitespace-nowrap text-[28px] font-semibold tracking-tight">
      {Array.from({ length: 4 }).map((_, i) => (
        <span key={i} className={i % 2 === 0 ? 'text-zinc-950' : 'text-zinc-300'}>
          {PHRASE}
        </span>
      ))}
    </div>
  );
}

function Scene({ progress }: { progress: MotionValue<number> }) {
  const baseX = useMotionValue(0);
  const velocity = useVelocity(progress);
  const smooth = useSpring(velocity, { damping: 50, stiffness: 400 });
  // speed multiplier: 1x at rest, up to 15x while flicking the scroller
  const boost = useTransform(smooth, (v) => 1 + Math.min(Math.abs(v) * 6, 14));
  const skewX = useTransform(smooth, [-2, 0, 2], [-8, 0, 8], { clamp: true });
  const barScale = useTransform(smooth, (v) => Math.min(Math.abs(v) / 1.5, 1));
  const x = useTransform(baseX, (v) => `${wrapRange(-50, 0, v)}%`);

  useAnimationFrame((_, delta) => {
    // 50% strip over ~4s at rest = 0.0125 percent per millisecond
    baseX.set(baseX.get() - 0.0125 * delta * boost.get());
  });

  return (
    <div className="relative" style={{ height: 1000 }}>
      <div className="sticky top-0 flex h-[320px] flex-col justify-center overflow-hidden bg-white">
        <div className="absolute inset-x-5 top-4 flex items-center justify-between">
          <span className="font-mono text-[10px] uppercase tracking-[0.16em] text-zinc-400">
            scroll velocity
          </span>
          <div className="h-0.5 w-16 overflow-hidden rounded-full bg-zinc-200">
            <motion.div className="h-full origin-left bg-zinc-950" style={{ scaleX: barScale }} />
          </div>
        </div>
        <motion.div style={{ x, skewX }} className="flex w-max will-change-transform">
          <MarqueeCopy />
          <MarqueeCopy />
        </motion.div>
        <p className="absolute inset-x-0 bottom-4 text-center text-[11px] text-zinc-400">
          在容器内快速滑动 —— 我会跟着加速并倾斜
        </p>
      </div>
    </div>
  );
}

/**
 * 滚动速度跑马灯 — a big-type marquee that cruises at a constant speed,
 * then instantly accelerates and skews with the scroller's velocity
 * (useVelocity + useSpring), springing back when you stop.
 */
export default function ScrollVelocity() {
  return (
    <ScrollShell className="w-[min(88%,440px)]">
      {({ progress }) => <Scene progress={progress} />}
    </ScrollShell>
  );
}

import { useRef } from 'react';
import type { ReactNode, RefObject } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import type { MotionValue } from 'framer-motion';
import { ArrowDown } from 'lucide-react';
import { cn } from '@/lib/utils';

const css = `
.mv-scroll {
  scrollbar-width: thin;
  scrollbar-color: #d4d4d8 transparent;
}
.mv-scroll::-webkit-scrollbar {
  width: 4px;
}
.mv-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.mv-scroll::-webkit-scrollbar-thumb {
  background: #d4d4d8;
  border-radius: 999px;
}
`;

export type ScrollCtx = {
  scrollerRef: RefObject<HTMLDivElement | null>;
  progress: MotionValue<number>;
};

type ScrollShellProps = {
  children: (ctx: ScrollCtx) => ReactNode;
  /** extra classes for the inner scroller (width / background overrides) */
  className?: string;
};

/**
 * Internal-scroll-container pattern shared by every scroll-narrative preview:
 * a 320px overflow-y viewport (page scroll is never hijacked) with a thin
 * custom scrollbar, a scroll-progress hairline pinned to the top, and a
 * "向下滚动" hint pill that fades out as soon as scrolling starts.
 * Children receive the container ref + a 0→1 scrollYProgress MotionValue.
 */
export default function ScrollShell({ children, className }: ScrollShellProps) {
  const scrollerRef = useRef<HTMLDivElement | null>(null);
  const { scrollYProgress } = useScroll({ container: scrollerRef });
  const hintOpacity = useTransform(scrollYProgress, [0, 0.06], [1, 0]);

  return (
    <div className="flex h-full w-full items-center justify-center">
      <style>{css}</style>
      <div className="relative flex w-full justify-center">
        <div
          ref={scrollerRef}
          /* Lenis 会在文档级劫持 wheel 事件，导致此容器只能拖滚动条；
             data-lenis-prevent 让滚轮在此容器内恢复原生滚动。 */
          data-lenis-prevent
          className={cn(
            'mv-scroll relative h-[320px] w-[400px] max-w-full overflow-y-auto overscroll-contain rounded-xl border border-zinc-200 bg-white',
            className,
          )}
        >
          <motion.div
            className="sticky top-0 z-40 h-0.5 origin-left bg-zinc-950/80"
            style={{ scaleX: scrollYProgress }}
          />
          {children({ scrollerRef, progress: scrollYProgress })}
        </div>
        <motion.div
          style={{ opacity: hintOpacity }}
          className="pointer-events-none absolute bottom-3 left-1/2 z-40 flex -translate-x-1/2 items-center gap-1.5 rounded-full border border-zinc-200 bg-white/90 px-2.5 py-1 text-[11px] text-zinc-500 shadow-sm backdrop-blur"
        >
          <motion.span
            animate={{ y: [0, 3, 0] }}
            transition={{ duration: 1.4, repeat: Infinity, ease: 'easeInOut' }}
            className="flex"
          >
            <ArrowDown className="h-3 w-3" />
          </motion.span>
          向下滚动
        </motion.div>
      </div>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

